<include file="Public:header"/><style type="text/css">    .table-list th{        width: 8%;    }</style><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Qiye/applyMoneyList')}" class="on">预充值审核</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:60%;">						<form action="{pigcms{:U('Qiye/applyMoneyList')}" method="get">                            <input type="hidden" name="c" value="Qiye"/>                            <input type="hidden" name="a" value="applyMoneyList"/>                            <font color="#000">搜索：</font>							<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">                                <option value="all" <if condition="$_GET['searchtype'] eq 'all'">selected="selected"</if>>请选择</option>								<option value="qiye_name" <if condition="$_GET['searchtype'] eq 'qiye_name'">selected="selected"</if>>企业名称</option>								<option value="staff_name" <if condition="$_GET['searchtype'] eq 'staff_name'">selected="selected"</if>>员工名称</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;                            <font color="#000">日期筛选：</font>                            <select name="searchTimeType">                                <option value="time" <if condition="$_GET['searchTimeType'] eq 'time'">selected="selected"</if>>申请时间</option>                                <option value="handle_time" <if condition="$_GET['searchTimeType'] eq 'handle_time'">selected="selected"</if>>审核时间</option>                            </select>                            <input type="text" class="input-text" name="begin_time" style="width:80px;" id="begin_time"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="text" class="input-text" name="end_time" style="width:80px;" id="end_time" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <font color="#000">状态筛选: </font><select name="searchstatus">                                <option value="-1" <if condition="$_GET['searchstatus'] eq -1">selected="selected"</if>>全部</option>                                <option value="0" <if condition="$_GET['searchstatus'] eq 0">selected="selected"</if>>待审核</option>								<option value="1" <if condition="$_GET['searchstatus'] eq 1">selected="selected"</if>>通过</option>                                <!--<option value="3" <if condition="$_GET['searchstatus'] eq 3">selected="selected"</if>>自动通过</option>-->								<option value="2" <if condition="$_GET['searchstatus'] eq 2">selected="selected"</if>>驳回</option>							</select>							<input type="submit" value="查询" class="button"/>                            <a href="javascript:void(0)" onclick="handle_all()" class="button">审核</a>													</form>					</td>				</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>                                <th><input type="checkbox" id="select_all" check-all="0"/></th>                                <th>ID</th>								<th>企业名称</th>                                <th>员工名称</th>                                <th>操作</th>                                <th>金额</th>                                <th>状态</th>                                <th>申请时间</th>                                <th>审核时间</th>                                <th>操作</th>						</thead>						<tbody>                        <notempty name="list">                            <volist name="list" id="l">                                <tr>                                    <td>                                        <if condition="$l['status'] eq 0">                                            <input class="apply_id" type="checkbox" name="ids[]" value="{pigcms{$l.id}"/>                                        <else/>                                            <input type="checkbox" disabled="disabled"/>                                        </if>                                    </td>                                    <td>{pigcms{$l.id}</td>                                    <td>{pigcms{$l.qiye_name}</td>                                    <td>{pigcms{$l.staff_name}</td>                                    <td><if condition="$l['operate'] EQ 1">预存<else/>扣减</if></td>                                    <td>{pigcms{$l.money}</td>                                    <td>                                        <if condition="$l['status'] eq 0">                                            待审核                                            <elseif condition="($l['status'] EQ 1) AND ($l['admin_account'] == '')"/>                                            自动通过                                            <elseif condition="$l['status'] EQ 1"/>                                            通过                                            <else/>                                            驳回                                        </if>                                    </td>                                    <td>{pigcms{$l.time|date='Y-m-d H:i:s',###}</td>                                    <td><php>echo $l['handle_time']>0?date('Y-m-d H:i:s',$l['handle_time']):'未审核';</php></td>                                    <td>                                        <if condition="$l['status'] EQ 0">                                            <a href="javascript:vod(0)" onclick="handle('{pigcms{$l.id}')">审核</a>    |                                        </if>                                            <a href="javascript:vod(0)" onclick="detail('{pigcms{$l.id}')">查看</>                                    </td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="13">{pigcms{$pagebar}</td></tr>                        <else/>                            <tr><td class="textcenter red" colspan="13">列表为空！</td></tr>                        </notempty>						</tbody>					</table>				</div>				</div><script>  function handle(id){      window.o2oTop.artiframe('{pigcms{:U('Qiye/handle')}'+'&id='+id,'审核',800,500,true,false,false,addbtn,'add',true);  }  function handle_all() {      var checked_apply = $('.apply_id:checked');      var len = checked_apply.length;      if (len < 1) {          alert('请选择一条记录');      } else {          var ids = '';          for (var i = 0; i < len; i++) {              if (ids == '') {                  ids = checked_apply[i].value;              } else {                  ids = ids + "," + checked_apply[i].value;              }          }          window.o2oTop.artiframe('{pigcms{:U('Qiye/handle')}'+'&id='+ids,'审核',800,250,true,false,false,addbtn,'add',true);      }  }  function detail(id){      window.o2oTop.artiframe('{pigcms{:U('Qiye/detail')}'+'&id='+id,'查看',800,500,true,false,false,false,'add',true);  }  $('#select_all').on('click', function () {      var check_all = $(this).attr('check-all');      if (check_all == "0") {          //全选          $('.apply_id').attr('checked', 'checked');          $(this).attr('check-all', 1);      } else {          //全不选          $('.apply_id').attr('checked', false);          $(this).attr('check-all', 0);      }  })</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>